/// <summary>
/// DebuC 22.09.23
/// </summary>
class NDXUmsatzAbschluss
{
    int         monat;          // Abschlussmonat
    int         jahr;           // Abschlussjahr
    int         offsetMonth;    // Default Vormonat also -1
}

Method.Source:
/// <summary>
/// DebuC 22.09.23
/// </summary>
/// <param name = "l_date">utcdatetime</param>
/// <param name = "l_offsetMonth">int</param>
/// <returns>NDXUmsatzAbschluss</returns>
static NDXUmsatzAbschluss construct(utcdatetime l_date = DateTimeUtil::utcNow(), int l_offsetMonth = -1)
{
    utcdatetime ldate;
    int loffsetMonth;
    ;
    ldate = l_date;
    loffsetMonth = l_offsetMonth;
    //--> 1.1 : NDX/PAFFH/NDX_TASK1235004210/04.12.2017
    if (prmisdefault(l_date))
    {
        ldate = NDXUmsatzParametersGlobal::getDateClose();
        loffsetMonth = 0;
    }
    //<-- 1.1 : NDX/PAFFH/NDX_TASK1235004210/04.12.2017
    return new NDXUmsatzAbschluss(ldate, loffsetMonth);
}

/// <summary>
/// DebuC 22.09.23
/// </summary>
/// <param name = "l_date">utcdatetime</param>
/// <param name = "l_offsetMonth">int</param>
protected void new(utcdatetime l_date = DateTimeUtil::utcNow(), int l_offsetMonth = -1)
{
    utcdatetime ldate;
    int loffsetMonth;
    ;
    ldate = l_date;
    loffsetMonth = l_offsetMonth;
    //--> 1.1 : NDX/PAFFH/NDX_TASK1235004210/04.12.2017
    if (prmisdefault(l_date))
    {
        ldate = NDXUmsatzParametersGlobal::getDateClose();
        loffsetMonth = 0;
    }
    //<-- 1.1 : NDX/PAFFH/NDX_TASK1235004210/04.12.2017
    offsetMonth = loffsetMonth;
    this.set(ldate);
}

/// <summary>
/// DebuC 22.09.23
/// </summary>
/// <param name = "l_date">utcdatetime</param>
void set(utcdatetime l_date = DateTimeUtil::utcNow())
{
    boolean lIsDefault = prmisdefault(l_date);
    utcdatetime ldate;
    ;
    ldate = l_date;
    //--> 1.1 : NDX/PAFFH/NDX_TASK1235004210/04.12.2017
    if (lIsDefault)
    {
        ldate = NDXUmsatzParametersGlobal::getDateClose();
    }
    //<-- 1.1 : NDX/PAFFH/NDX_TASK1235004210/04.12.2017
    monat   = DateTimeUtil::month(ldate);
    jahr    = DateTimeUtil::year(ldate);

    if (lIsDefault)
    {
        // Abschlussmonat um Faktor -1 korrigieren
        if (offsetMonth)
        {
            if (monat + offsetMonth <= 0)
            {
                monat   = 12;
                jahr    = jahr - 1;
            }
            else
            {
                monat += offsetMonth;
            }
        }
    }
}

/// <summary>
/// DebuC 08.08.24
/// </summary>
/// <returns>NDXMonthBE</returns>
NDXMonthBE getMonthBE()
{
    switch (monat)
    {
        case 1 :    
            return NDXMonthBE::January;
        case 2 :
            return NDXMonthBE::February;
        case 3 :
            return NDXMonthBE::March;
        case 4 :
            return NDXMonthBE::April;
        case 5 :
            return NDXMonthBE::May;
        case 6 :
            return NDXMonthBE::June;
        case 7 :
            return NDXMonthBE::July;
        case 8 :
            return NDXMonthBE::August;
        case 9 :
            return NDXMonthBE::September;
        case 10:
            return NDXMonthBE::October;
        case 11:
            return NDXMonthBE::November;
        case 12:
            return NDXMonthBE::December;
        default:
            throw error(strfmt('@Monat [%1] wird nicht berücksichtigt!', monat));      // Monat [%1] wird nicht berücksichtigt!
    }
}
